<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Holder\UserAccessTemporalCodeRegisterCodeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeRegisterCodeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserAccessTemporalCodeRegisterCodeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRegisterCode returns null on a freshly created holder.
     */
    public function testRegisterCodeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRegisterCodeAssigned());
        $this->assertNull($holder->getRegisterCode());
    }
}
class ImplWithUserAccessTemporalCodeRegisterCodeAttributeHolderUnitTest
{
    use UserAccessTemporalCodeRegisterCodeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRegisterCodeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRegisterCode();
    }
}
